package mrpapermoon.whisper.service.internalimport android.content.Contextimport com.google.android.gms.nearby.Nearbyimport com.google.android.gms.nearby.connection.AdvertisingOptionsimport com.google.android.gms.nearby.connection.ConnectionInfoimport com.google.android.gms.nearby.connection.ConnectionLifecycleCallbackimport com.google.android.gms.nearby.connection.ConnectionResolutionimport com.google.android.gms.nearby.connection.ConnectionsClientimport com.google.android.gms.nearby.connection.DiscoveredEndpointInfoimport com.google.android.gms.nearby.connection.DiscoveryOptionsimport com.google.android.gms.nearby.connection.EndpointDiscoveryCallbackimport com.google.android.gms.nearby.connection.Payloadimport com.google.android.gms.nearby.connection.Strategyimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Deferredimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.mapimport kotlinx.coroutines.tasks.asDeferredimport mrpapermoon.whisper.service.NearbyConnectionEventimport mrpapermoon.whisper.service.NearbyConnectionsAdapterimport mrpapermoon.whisper.tools.awaitResultimport mrpapermoon.whisper.tools.logResultimport java.util.concurrent.CopyOnWriteArrayListimport java.util.concurrent.CopyOnWriteArraySetinternal open class NearbyConnectionsAdapterImpl(context: Context, scope: CoroutineScope, uuid: String) :	NearbyConnectionsAdapter(scope, uuid),	ConnectionsClient by Nearby.getConnectionsClient(context) {	final override val activeEndpoints: List<String>		field = CopyOnWriteArrayList<String>()	final override val ignoreEndpoints: List<String>		field = CopyOnWriteArrayList<String>()	private val strategy		get() = Strategy.P2P_CLUSTER	private val logger = KotlinLogging.logger {}	override suspend fun stopAllConnections() {		super.stopAllConnections()		logger.debug { "stopDiscovery" }		stopDiscovery()		logger.debug { "stopAdvertising" }		stopAdvertising()		logger.debug { "stopAllEndpoints" }		stopAllEndpoints()		activeEndpoints.clear()		ignoreEndpoints.clear()	}	override fun startDiscovery(): Deferred<Void> {		logger.info { "startDiscovery" }		val discoveryOptions = DiscoveryOptions.Builder()			.setStrategy(strategy)			.build()		return startDiscovery(			SERVICE_ID,			DiscoveryCallback(),			discoveryOptions,		)			.logResult("Discovery")			.asDeferred()	}	override fun startAdvertising(): Deferred<Void> {		logger.info { "startAdvertising" }		val advertisingOptions = AdvertisingOptions.Builder()			.setStrategy(strategy)			.build()		val connectionCallback = ConnectionCallback(imHosting = false)		emitFlatten(connectionCallback)		return startAdvertising(			uuid,			SERVICE_ID,			connectionCallback,			advertisingOptions,		)			.logResult("Advertising", uuid)			.asDeferred()	}	override suspend fun sendPayloadBytes(endpointId: String, byteArray: ByteArray) {		sendPayload(endpointId, Payload.fromBytes(byteArray))			.awaitResult("sendPayloadBytes", endpointId)	}	private inner class DiscoveryCallback : EndpointDiscoveryCallback() {		private val discoveryConnections = CopyOnWriteArraySet<String>()		override fun onEndpointFound(			endpointId: String,			info: DiscoveredEndpointInfo,		) {			logger.debug { "onEndpointFound(endpointId: $endpointId, info: ${info.dumpString()})" }			if (ignoreEndpoints.contains(endpointId)) {				rejectConnection(endpointId)				logger.debug { "ignore $endpointId" }				return			}			if (discoveryConnections.contains(endpointId) || activeEndpoints.contains(endpointId)) {				logger.warn { "Endpoint $endpointId is already connected" }				return			}			discoveryConnections += endpointId			val connectionLifecycleCallback = ConnectionCallback(imHosting = true)			emitFlatten(connectionLifecycleCallback)			requestConnection(uuid, endpointId, connectionLifecycleCallback)				.addOnCompleteListener {					discoveryConnections -= endpointId				}				.logResult("request connection", endpointId, info)		}		override fun onEndpointLost(endpointId: String) {			logger.debug { "onEndpointLost(endpointId: $endpointId)" }			discoveryConnections -= endpointId		}	}	private inner class ConnectionCallback private constructor(		private val imHosting: Boolean,		private val innerFlow: MutableSharedFlow<NearbyConnectionEvent>	) : ConnectionLifecycleCallback(),		Flow<NearbyConnectionEvent> by innerFlow {		constructor(imHosting: Boolean) : this(imHosting, MutableSharedFlow<NearbyConnectionEvent>())		override fun onConnectionInitiated(endpointId: String, connectionInfo: ConnectionInfo) {			logger.debug { "onConnectionInitiated(endpointId: $endpointId, connectionInfo: ${connectionInfo.dumpString()})" }			if (imHosting && ignoreEndpoints.contains(endpointId)) {				disconnectFromEndpoint(endpointId)				logger.debug { "Reject connection(endpointId: $endpointId)" }				return			}			val bytesPayloadCallback = BytesPayloadCallback()			acceptConnection(endpointId, bytesPayloadCallback)				.logResult("Accept connection", imHosting, endpointId, connectionInfo)			val flow = bytesPayloadCallback				.map { event ->					when (event) {						is FlowPayloadCallback.Event.OnBytesPayloadReceived -> {							NearbyConnectionEvent.OnBytesPayloadReceived(endpointId, event.payload)						}						is FlowPayloadCallback.Event.OnStreamPayloadReceived -> {							NearbyConnectionEvent.OnFlowPayloadReceived(endpointId, event.byteStream)						}						is FlowPayloadCallback.Event.OnUnsupportedPayloadReceived -> {							ignoreEndpoints += endpointId							disconnectFromEndpoint(endpointId)							logger.debug { "Reject connection OnUnsupportedPayloadReceived(endpointId: $endpointId)" }							// TODO: проверить что не будет дублироваться с onDisconnected							NearbyConnectionEvent.OnDropConnection(endpointId)						}					}				}			innerFlow emitEventSource flow		}		override fun onConnectionResult(endpointId: String, result: ConnectionResolution) {			val status = result.status			logger.debug { "onConnectionResult(endpointId: $endpointId, status: $status)" }			if (!status.isSuccess) {				if (!status.isCanceled && !status.isInterrupted) {					logger.warn { "OnConnectionResult failed: statusCode >${status.statusCode} statusMessage >${status.statusMessage}" }					ignoreEndpoints += endpointId				}				return			}			activeEndpoints += endpointId			innerFlow emitEvent NearbyConnectionEvent.OnConnection(endpointId, imHosting)		}		override fun onDisconnected(endpointId: String) {			logger.debug { "OnDisconnect(endpointId: $endpointId)" }			activeEndpoints -= endpointId			innerFlow emitEvent NearbyConnectionEvent.OnDisconnected(endpointId)		}	}}